negativeExample:
import java.util.function.BiConsumer;
import java.util.function.Runnable;

public class Example {
    void acceptBiConsumer(BiConsumer<String, String> consumer) {
        consumer.accept("Hello", "World");
    }

    void acceptRunnable(Runnable runnable) {
        runnable.run();
    }

    void foo() {
        acceptBiConsumer((s, t) -> { System.out.println(s + t); }); // Multiple parameters, should not match
        acceptRunnable(() -> { System.out.println("No parameters"); }); // No parameters, should not match
    }
}
